package com.abhishek.ecommerce.order;
import com.abhishek.ecommerce.common.DomainEvent;import org.apache.kafka.clients.admin.NewTopic;import org.springframework.context.annotation.*;import org.springframework.kafka.support.serializer.JsonSerializer;import org.springframework.kafka.core.*;import org.springframework.kafka.core.DefaultKafkaProducerFactory;import java.util.*;
@Configuration public class KafkaConfig{@Bean NewTopic orderEvents(){return new NewTopic("order-events",1,(short)1);}@Bean NewTopic paymentEvents(){return new NewTopic("payment-events",1,(short)1);}@Bean ProducerFactory<String,DomainEvent> producerFactory(){Map<String,Object>p=new HashMap<>();p.put("bootstrap.servers","localhost:9092");p.put("key.serializer","org.apache.kafka.common.serialization.StringSerializer");p.put("value.serializer",JsonSerializer.class);return new DefaultKafkaProducerFactory<>(p);}@Bean KafkaTemplate<String,DomainEvent>kafkaTemplate(){return new KafkaTemplate<>(producerFactory());}}